import{_ as t,o as a,c as i,a0 as s}from"./chunks/framework.Bogozrur.js";const c=JSON.parse('{"title":"The Gatekeeper (Auth)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/auth.md","filePath":"guide/auth.md"}'),o={name:"guide/auth.md"};function l(n,e,r,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="the-gatekeeper-auth" tabindex="-1">The Gatekeeper (Auth) <a class="header-anchor" href="#the-gatekeeper-auth" aria-label="Permalink to &quot;The Gatekeeper (Auth)&quot;">​</a></h1><p>Jengo&#39;s &quot;Gatekeeper&quot; provides a robust, beautifully styled authentication system out of the box, built on top of the official <strong>CodeIgniter Shield</strong>.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>The easiest way to get the Gatekeeper is to use the <code>--auth</code> flag during project creation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jengo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auth</span></span></code></pre></div><p>If you already have a Jengo project and want to add authentication later, you can run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jengo:setup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span></span></code></pre></div><h2 id="smart-integration" tabindex="-1">Smart Integration <a class="header-anchor" href="#smart-integration" aria-label="Permalink to &quot;Smart Integration&quot;">​</a></h2><p>The Jengo installer is smart enough to adapt the authentication UI based on your chosen starter kit.</p><h3 id="_1-default-php-kit" tabindex="-1">1. Default PHP Kit <a class="header-anchor" href="#_1-default-php-kit" aria-label="Permalink to &quot;1. Default PHP Kit&quot;">​</a></h3><p>If you are using the default PHP kit, the installer will publish highly polished, Tailwind-styled <code>login.php</code> and <code>register.php</code> views directly into <code>app/Views/Shield/</code>. It automatically configures Shield to use these custom views instead of the default ones.</p><h3 id="_2-inertia-spa-kits-react-vue-svelte" tabindex="-1">2. Inertia SPA Kits (React, Vue, Svelte) <a class="header-anchor" href="#_2-inertia-spa-kits-react-vue-svelte" aria-label="Permalink to &quot;2. Inertia SPA Kits (React, Vue, Svelte)&quot;">​</a></h3><p>If you install the Gatekeeper alongside an Inertia kit, Jengo skips the PHP views entirely. Instead, it:</p><ol><li>Publishes a suite of Inertia-friendly controllers to <code>app/Controllers/Auth/</code>: <ul><li><code>LoginController</code>: Handles SPA login and logout.</li><li><code>RegisterController</code>: Handles SPA user registration.</li><li><code>MagicLinkController</code>: Manages email-based, passwordless login.</li><li><code>ActionController</code>: Handles multi-step auth actions (e.g., 2FA, Email Verification).</li></ul></li><li>Re-routes the default Shield endpoints to these custom controllers.</li><li>Scaffolds complete, working authentication pages in your chosen framework (React, Vue, or Svelte).</li></ol><p>This ensures a seamless, page-refresh-free authentication experience for modern Single Page Applications.</p>',15)])])}const g=t(o,[["render",l]]);export{c as __pageData,g as default};
